// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(c.tokenBalance(caller) == 0);
        // Ensure supportsToken returns true for "Nu Token"
        bytes32 expected = keccak256(abi.encodePacked("Nu Token"));
        vm.mockCall(
            caller,
            abi.encodeWithSignature("supportsToken()"),
            abi.encode(expected)
        );
        uint256 balanceBefore = c.tokenBalance(caller);
        vm.prank(caller);
        c.airDrop();
        uint256 balanceAfter = c.tokenBalance(caller);
        assertTrue(balanceAfter >= balanceBefore, "Balance should not decrease");
    }
}

